function hasSpecialSubstring(s, k) {
  // Test every window of length k against the rules directly.
  for (let start = 0; start + k <= s.length; start++) {
    const letter = s[start];
    if (s.slice(start, start + k) !== letter.repeat(k)) continue;
    if (start > 0 && s[start - 1] === letter) continue;
    if (start + k < s.length && s[start + k] === letter) continue;
    return true;
  }
  return false;
}

