function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const length = size === 'large' ? 100 : int(1, 10);
  const letters = 'abcdefghijklmnopqrstuvwxyz'.slice(0, size === 'large' ? int(2, 26) : int(1, 3));
  // Build the string from blocks of one letter; neighbouring blocks of the same letter merge into longer runs.
  let s = '';
  while (s.length < length) s += letters[int(0, letters.length - 1)].repeat(Math.min(length - s.length, int(1, size === 'large' ? 12 : 4)));
  // Half the time k is the length of a run that exists, so both answers are common.
  const runs = s.match(/(.)\1*/g).map(run => run.length);
  return [s, rand() < 0.5 ? runs[int(0, runs.length - 1)] : int(1, length)];
}
